package com.example.starter.feed.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

import java.math.BigDecimal;
import java.util.List;

/**
 * 配方提交请求；每次提交生成一个独立新版本，新版本独立做合规校验。
 *
 * @param requestId    幂等键，非空
 * @param formulaCode  配方编码（同编码下版本递增）
 * @param targetSpecies 目标动物种类；含药配方必填且须与投产批次物种一致
 * @param items        配方组成：原料/药物添加剂编码 + 添加比例（0~1 之间的小数，恰等于目录上限合法）
 */
public record SubmitFormulaRequest(
        @NotBlank String requestId,
        @NotBlank String formulaCode,
        String targetSpecies,
        @NotNull List<Item> items) {

    /**
     * 配方组成项。
     *
     * @param ingredientCode 原料或药物添加剂目录编码
     * @param ratio          添加比例（占全价饲料比例，如 0.002 表示 0.2%）
     */
    public record Item(@NotBlank String ingredientCode, @NotNull @PositiveOrZero BigDecimal ratio) {
    }
}

package com.example.starter.feed.api;

import java.math.BigDecimal;
import java.util.List;

/**
 * 配方版本视图，提交/批准接口均返回该结构。
 *
 * @param formulaCode   配方编码
 * @param versionNo     版本号（同配方内自增）
 * @param status        SUBMITTED / REJECTED / APPROVED
 * @param targetSpecies 目标动物种类；非含药配方可为空
 * @param medicated     是否含药物添加剂
 * @param items         版本冻结时的组成项快照
 * @param rejectReasons 合规拒绝原因；通过时为空列表
 */
public record FormulaView(
        String formulaCode,
        int versionNo,
        String status,
        String targetSpecies,
        boolean medicated,
        List<Item> items,
        List<String> rejectReasons) {

    /**
     * 组成项视图。
     */
    public record Item(String ingredientCode, String ingredientName, BigDecimal ratio) {
    }
}

package com.example.starter.feed.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 配方批准请求；仅 SUBMITTED（合规校验通过）版本可批准，批准后内容冻结。
 *
 * @param requestId   幂等键
 * @param formulaCode 配方编码
 * @param versionNo   待批准版本号
 */
public record ApproveFormulaRequest(
        @NotBlank String requestId,
        @NotBlank String formulaCode,
        @NotNull Integer versionNo) {
}

package com.example.starter.feed.api;

import jakarta.validation.constraints.NotBlank;

import java.time.Instant;

/**
 * 含药配方投产请求：将一个已批准冻结版本投产到指定养殖批次，并登记末次饲喂含药饲料时刻。
 *
 * @param requestId       幂等键
 * @param batchNo         养殖批次号
 * @param formulaCode     配方编码
 * @param versionNo       指定投产版本；为空时取该配方最新已批准版本
 * @param lastFeedingTime 末次饲喂该含药饲料的时刻（UTC，ISO-8601），休药期从该时刻所在 UTC 日起算
 */
public record ProductionRequest(
        @NotBlank String requestId,
        @NotBlank String batchNo,
        @NotBlank String formulaCode,
        Integer versionNo,
        Instant lastFeedingTime) {
}

package com.example.starter.feed.api;

import java.time.Instant;
import java.time.LocalDate;

/**
 * 投产结果视图。
 *
 * @param batchNo               养殖批次号
 * @param formulaCode           投产配方编码
 * @param versionNo             实际投产的冻结版本号
 * @param lastFeedingTime       本次登记的末次含药饲喂时刻
 * @param batchLastFeedingTime  合并后批次最晚末次含药饲喂时刻
 * @param maxWithdrawalDays     合并后批次涉及药物中的最大休药天数（单位：天，整数日界）
 * @param earliestSlaughterDate 最早合法出栏日（UTC）：恰满休药天数当日 24:00 后可出栏，即次日 00:00 UTC 起合法
 */
public record ProductionView(
        String batchNo,
        String formulaCode,
        int versionNo,
        Instant lastFeedingTime,
        Instant batchLastFeedingTime,
        int maxWithdrawalDays,
        LocalDate earliestSlaughterDate) {
}

package com.example.starter.feed.api;

import jakarta.validation.constraints.NotBlank;

import java.time.Instant;

/**
 * 出栏申请。
 *
 * @param requestId 幂等键
 * @param batchNo   养殖批次号
 * @param applyTime 申请出栏时刻（UTC，ISO-8601）；为空时取服务端当前时刻
 */
public record SlaughterRequest(
        @NotBlank String requestId,
        @NotBlank String batchNo,
        Instant applyTime) {
}

package com.example.starter.feed.api;

import java.time.Instant;
import java.time.LocalDate;

/**
 * 出栏申请结果。
 *
 * @param batchNo               养殖批次号
 * @param accepted              是否允许出栏
 * @param status                批次状态：ACTIVE / SLAUGHTERED
 * @param repeated              是否为出栏终态后的重复申请（幂等成功）
 * @param earliestSlaughterDate 最早合法出栏日（UTC）；休药期内被拒绝时回传
 * @param slaughteredAt         实际出栏时刻；尚未出栏为空
 * @param rejectReason          拒绝原因；接受时为空
 */
public record SlaughterView(
        String batchNo,
        boolean accepted,
        String status,
        boolean repeated,
        LocalDate earliestSlaughterDate,
        Instant slaughteredAt,
        String rejectReason) {
}

package com.example.starter.feed.api;

import jakarta.validation.constraints.NotBlank;

import java.time.Instant;

/**
 * 含药饲喂记录上报请求（用于模拟饲喂记录延迟到达等场景）。
 *
 * @param batchNo      养殖批次号
 * @param formulaCode  含药配方编码
 * @param versionNo    配方版本号；为空时取最新已批准版本
 * @param feedingTime  实际饲喂时刻（UTC，ISO-8601）
 */
public record FeedingRecordRequest(
        @NotBlank String batchNo,
        @NotBlank String formulaCode,
        Integer versionNo,
        Instant feedingTime) {
}

