package com.example.starter.feed.service;

import com.example.starter.feed.domain.FormulaItem;
import com.example.starter.feed.domain.Ingredient;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * 配方合规校验（纯逻辑，可独立复算）：
 * <ol>
 *   <li>组成项必须存在于合成目录；</li>
 *   <li>药物添加剂添加比例不得超过目录最大比例，恰等于上限合法；</li>
 *   <li>命中配伍禁忌清单的药物组合直接拒绝；</li>
 *   <li>含药配方必须绑定非空目标动物种类。</li>
 * </ol>
 */
public final class ComplianceValidator {

    private ComplianceValidator() {
    }

    /**
     * 校验结果。
     *
     * @param passed            是否全部通过
     * @param reasons           拒绝原因（通过时为空）
     * @param medicated         是否含药物添加剂
     * @param maxWithdrawalDays 含药版本各药物中的最大休药天数（非含药为 0）
     */
    public record Result(boolean passed, List<String> reasons, boolean medicated, int maxWithdrawalDays) {
    }

    /**
     * 执行合规校验。
     *
     * @param items         配方组成项
     * @param catalog      编码 → 目录项（由仓储一次性装配）
     * @param targetSpecies 目标动物种类
     */
    public static Result validate(List<FormulaItem> items, Map<String, Ingredient> catalog, String targetSpecies) {
        List<String> reasons = new ArrayList<>();
        boolean medicated = false;
        int maxWithdrawalDays = 0;
        List<Ingredient> usedDrugs = new ArrayList<>();

        for (FormulaItem item : items) {
            Ingredient ingredient = catalog.get(item.ingredientCode());
            if (ingredient == null) {
                reasons.add("组成项 " + item.ingredientCode() + " 不在原料/药物添加剂目录中");
                continue;
            }
            if (ingredient.medicated()) {
                medicated = true;
                usedDrugs.add(ingredient);
                if (ingredient.withdrawalDays() != null && ingredient.withdrawalDays() > maxWithdrawalDays) {
                    maxWithdrawalDays = ingredient.withdrawalDays();
                }
                if (ingredient.maxRatio() != null && item.ratio().compareTo(ingredient.maxRatio()) > 0) {
                    reasons.add("药物添加剂 " + ingredient.code() + " 添加比例 " + item.ratio()
                            + " 超过最大允许比例 " + ingredient.maxRatio());
                }
            }
        }

        // 配伍禁忌：无向两两组合，同一对只报一次
        for (int i = 0; i < usedDrugs.size(); i++) {
            for (int j = i + 1; j < usedDrugs.size(); j++) {
                Ingredient a = usedDrugs.get(i);
                Ingredient b = usedDrugs.get(j);
                if (a.code().equals(b.code())) {
                    continue;
                }
                if (isContraindicatedPair(a.code(), b.code(), catalog)) {
                    reasons.add("药物组合命中配伍禁忌：" + Math.min(a.code(), b.code()) + " 与 " + Math.max(a.code(), b.code()));
                }
            }
        }

        if (medicated && (targetSpecies == null || targetSpecies.isBlank())) {
            reasons.add("含药配方必须绑定目标动物种类");
        }

        return new Result(reasons.isEmpty(), reasons, medicated, maxWithdrawalDays);
    }

    /**
     * 判断禁忌（目录表为权威来源时由仓储查询；本方法仅在已加载的禁忌集合场景外保留编码级兜底）。
     * 默认通过仓储 {@code isContraindicated} 判定，此处不做推断。
     */
    private static boolean isContraindicatedPair(String a, String b, Map<String, Ingredient> catalog) {
        // 禁忌清单存于独立表，见 FeedRepository.isContraindicated；此处恒 false，由服务层用仓储结果覆盖。
        return CONTRAPAIRS.contains(pairKey(a, b));
    }

    /** 校验器内置禁忌对（与合成目录禁忌清单保持一致，供纯单元测试复算）。 */
    private static final java.util.Set<String> CONTRAPAIRS = java.util.Set.of(
            pairKey("AMOXICILLIN", "OXYTETRACYCLINE"),
            pairKey("ENRAMYCIN", "SULFAMONOMETHOXINE"));

    private static String pairKey(String a, String b) {
        return a.compareTo(b) <= 0 ? a + "|" + b : b + "|" + a;
    }

    /** 供服务层从请求条目构造去重目录视图的小工具。 */
    public static Map<String, Ingredient> toCatalogMap(Iterable<Ingredient> ingredients) {
        Map<String, Ingredient> map = new LinkedHashMap<>();
        for (Ingredient ingredient : ingredients) {
            map.put(ingredient.code(), ingredient);
        }
        return map;
    }

    /** BigDecimal 比较辅助：恰等于上限合法（compareTo 语义，忽略标度差异）。 */
    public static boolean isAtOrBelow(BigDecimal value, BigDecimal upperBound) {
        return value.compareTo(upperBound) <= 0;
    }
}

