        return new Result(reasons.isEmpty(), reasons, medicated, maxWithdrawalDays);
    }

    /**
     * 判断禁忌（目录表为权威来源时由仓储查询；本方法仅在已加载的禁忌集合场景外保留编码级兜底）。
     * 默认通过仓储 {@code isContraindicated} 判定，此处不做推断。
     */
    private static boolean isContraindicatedPair(String a, String b, Map<String, Ingredient> catalog) {
        // 禁忌清单存于独立表，见 FeedRepository.isContraindicated；此处恒 false，由服务层用仓储结果覆盖。
        return CONTRAPAIRS.contains(pairKey(a, b));
    }

    /** 校验器内置禁忌对（与合成目录禁忌清单保持一致，供纯单元测试复算）。 */
    private static final java.util.Set<String> CONTRAPAIRS = java.util.Set.of(
            pairKey("AMOXICILLIN", "OXYTETRACYCLINE"),
            pairKey("ENRAMYCIN", "SULFAMONOMETHOXINE"));

    private static String pairKey(String a, String b) {
        return a.compareTo(b) <= 0 ? a + "|" + b : b + "|" + a;
    }

    /** 供服务层从请求条目构造去重目录视图的小工具。 */
    public static Map<String, Ingredient> toCatalogMap(Iterable<Ingredient> ingredients) {
        Map<String, Ingredient> map = new LinkedHashMap<>();
        for (Ingredient ingredient : ingredients) {
            map.put(ingredient.code(), ingredient);
        }
        return map;
    }

    /** BigDecimal 比较辅助：恰等于上限合法（compareTo 语义，忽略标度差异）。 */
    public static boolean isAtOrBelow(BigDecimal value, BigDecimal upperBound) {
        return value.compareTo(upperBound) <= 0;
    }
}

