        assertThat(Fingerprints.of("SUBMIT", "R2",
                request("R2", "F-A", "POULTRY", "0.001"))).isNotEqualTo(base);
        // 操作类型也参与摘要，防跨操作串用
        assertThat(Fingerprints.of("PRODUCTION", "R1",
                request("R1", "F-A", "POULTRY", "0.001"))).isNotEqualTo(base);
    }

    @Test
    void instantsAreSerializedStably() {
        SubmitFormulaRequest r1 = new SubmitFormulaRequest("R1", "F", "POULTRY",
                List.of(new SubmitFormulaRequest.Item("CORN", BigDecimal.ONE)));
        String f1 = Fingerprints.of("SUBMIT", "R1", r1);
        String f2 = Fingerprints.of("SUBMIT", "R1", r1);
        assertThat(f1).isEqualTo(f2);
        assertThat(Instant.parse("2026-09-01T00:00:00Z")).isNotNull();
    }
}

